<div class="chart-legend"><span><i class="swatch income"></i>Income</span><span><i class="swatch expense"></i>Expenses</span><span><i class="swatch balance"></i>Balance</span></div>
<div class="chart-container"><canvas class="cash-chart" data-chart="<?= e(json_encode($chart)) ?>" data-currency="<?= e(workspace()['currency']) ?>" role="img" aria-label="Monthly income, expenses and net balance. Exact values are available below."></canvas><div class="chart-tooltip" hidden></div></div>
<details class="chart-data"><summary>View chart data</summary><div class="table-wrap"><table><thead><tr><th>Month</th><th>Income</th><th>Expenses</th><th>Balance</th></tr></thead><tbody><?php foreach($chart as $point): ?><tr><td><?= e($point['label']) ?></td><td><?= money($point['income']) ?></td><td><?= money($point['expenses']) ?></td><td><?= money($point['balance']) ?></td></tr><?php endforeach ?></tbody></table></div></details>
